const baseState = () => ({plan:'free',profile:{name:'',level:'Mahasiswa',skills:[],experience:'',hours:8,budget:'Gratis'},career:'frontend',ready:false,step:1,cvLoaded:false,consent:false,tasks:{},saved:[],activity:[],lastEvaluation:null,evaluations:[],weeklyGoal:3});
let state = baseState();
try {
 const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
 if(saved && typeof saved === 'object'){
  state={...state,...saved,profile:{...state.profile,...saved.profile}};
  state.plan=state.plan==='plus'?'plus':'free';
  if(!careers.some(c=>c.id===state.career)) state.career='frontend';
  state.profile.skills=Array.isArray(state.profile.skills)?state.profile.skills.filter(s=>skillList.includes(s)):[];
  state.profile.hours=[4,8,12].includes(Number(state.profile.hours))?Number(state.profile.hours):8;
  state.saved=Array.isArray(state.saved)?state.saved.filter(x=>resources[x]):[];
  state.activity=Array.isArray(state.activity)?state.activity.slice(0,40):[];
  state.evaluations=Array.isArray(state.evaluations)?state.evaluations.filter(x=>x&&careers.some(c=>c.id===x.career)&&Array.isArray(x.skills)).slice(0,50):[];
  state.weeklyGoal=[1,3,6,9,12,18].includes(Number(state.weeklyGoal))?Number(state.weeklyGoal):3;
  state.tasks=state.tasks && typeof state.tasks==='object'?state.tasks:{};
  state.step=state.step===2?2:1;
 }
} catch { state=baseState(); }
const ui={category:'all',careerSearch:'',resourceFilter:'all',menu:false,uploading:false,generating:false};
const save=()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{}};
const career=()=>careers.find(c=>c.id===state.career)||careers[0];
const weeks=()=>Math.max(4,Math.ceil(career().hours/state.profile.hours));
const taskKey=(i,j)=>`${state.career}-${i}-${j}`;
const progress=()=>{
 let done=0,total=0;
 career().stages.forEach((s,i)=>s.tasks.forEach((_,j)=>{total++;if(state.tasks[taskKey(i,j)])done++;}));
 return {done,total,percent:Math.round(done/total*100)};
};
const stageProgress=i=>{const t=career().stages[i].tasks;return Math.round(t.filter((_,j)=>state.tasks[taskKey(i,j)]).length/t.length*100);};
const activeStage=()=>{const stages=career().stages;let i=stages.findIndex((s,i)=>stageProgress(i)<100&&!known(s));if(i<0&&stageProgress(stages.length-1)<100)i=stages.length-1;if(i<0)i=stages.findIndex((_,i)=>stageProgress(i)<100);return i<0?stages.length-1:i;};
const known=s=>s.skills.length>0 && s.skills.every(k=>state.profile.skills.includes(k));
const dateLabel=iso=>{try{return new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(iso));}catch{return 'Baru saja';}};
const skillOptions=(selected=[])=>skillList.map(s=>`<label class="skill-check"><input type="checkbox" name="skills" value="${esc(s)}"${selected.includes(s)?' checked':''}>${esc(s)}</label>`).join('');
const route=()=>location.hash.replace(/^#\/?/,'').split('?')[0]||'home';
function go(page){closeModal();ui.menu=false;const hash='#/'+page;if(location.hash===hash){render();window.scrollTo(0,0);}else location.hash=hash;}
function start(plan=state.plan, id=state.career){state.plan=plan;state.career=id;state.step=1;save();go('onboarding');}
function showToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),3200);}
function tag(){return `<span class="tag${state.plan==='plus'?' plus-tag':''}">${state.plan==='plus'?icon('sparkle',true)+' Plus':'Free'}</span>`;}
function closeMobileMenu(){
 ui.menu=false;
 $('.nav-links')?.classList.remove('open');
 const button=$('.mobile-menu');
 if(button){button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Buka navigasi');button.innerHTML=icon('menu');}
}
function header(){return `<header class="site-header"><nav class="container nav" aria-label="Navigasi utama">${logo()}<div id="site-navigation" class="nav-links${ui.menu?' open':''}"><a href="#/home">Beranda</a><a href="#/careers">Jalur karier</a><button data-action="scroll" data-id="how">Cara kerja</button><button data-action="scroll" data-id="plans">Paket belajar</button></div><div class="nav-actions"><span class="demo-label">PROTOTYPE</span><button class="text-link" data-action="dashboard">${state.ready?'Dashboard saya':'Masuk demo'}</button><button class="btn small-btn" data-action="start">Mulai belajar ${icon('arrow',true)}</button><button class="mobile-menu" data-action="menu" aria-label="${ui.menu?'Tutup navigasi':'Buka navigasi'}" aria-controls="site-navigation" aria-expanded="${ui.menu}">${icon(ui.menu?'close':'menu')}</button></div></nav></header>`;}
function footer(){return `<footer class="site-footer"><div class="container row between">${logo()}<p>© 2026 Pathwise. Prototype CareerPilot AI.</p><div class="footer-right"><button data-action="privacy">Privasi demo</button><a href="#/careers">Jalur karier</a><button data-action="scroll" data-id="plans">Free & Plus</button></div></div></footer>`;}
function art(c){let visual=c.id==='frontend'?'<div class="art-browser"><div class="art-toolbar"><i></i><i></i><i></i></div><div class="art-code"><i></i><i></i><i></i><i></i></div></div>':c.id==='data'?'<div class="art-bars"><i style="height:36%"></i><i style="height:70%"></i><i style="height:52%"></i><i style="height:95%"></i><i style="height:78%"></i></div>':`<div class="big-symbol">${esc(c.symbol)}</div>`;return `<div class="career-art" style="--card-color:${c.color};--card-ink:${c.ink};color:${c.ink}"><span class="art-orbit"></span>${visual}</div>`;}
function careerCard(c){return `<article class="career-card" data-career-card="${c.id}">${art(c)}<div class="career-body"><span class="career-category">${c.label}</span><h3>${c.name}</h3><p>${c.desc}</p><div class="career-meta"><span>${icon('clock',true).replace('class="icon sm"','class="icon sm" style="display:inline;vertical-align:-4px;margin-right:4px"')} Est. ${c.hours} jam</span><button class="text-link" data-action="choose-start" data-career="${c.id}">Pilih jalur ${icon('arrow',true)}</button></div></div></article>`;}
function home(){return `${header()}<main id="main-content" class="fade-in"><section class="hero"><div class="container hero-inner"><div class="hero-copy"><div class="eyebrow">${icon('sparkle',true)} Mulai dari kemampuanmu hari ini</div><h1>Belajar IT,<br>lebih jelas<br><span>arahnya.</span></h1><p>Punya tujuan, tapi belum tahu mulai dari mana? Susun roadmap belajar yang sesuai kemampuan, waktu, dan arah kariermu.</p><div class="hero-ctas"><button class="btn orange" data-action="start">Susun roadmap saya ${icon('arrow',true)}</button><a class="text-link" href="#/careers">Jelajahi jalur karier ${icon('arrow',true)}</a></div><div class="hero-note">${icon('check',true)} Roadmap awal gratis. Mulai tanpa pembayaran.</div></div><div class="hero-art" aria-label="Ilustrasi belajar dengan roadmap pribadi"><div class="photo-blob"><img src="assets/student.jpg" alt="Seorang pelajar membawa buku" width="900" height="1200" fetchpriority="high"></div><span class="spark" aria-hidden="true">✳</span><span class="spark small-spark" aria-hidden="true">✦</span><div class="floating hero-float-top"><div class="soft-icon">${icon('target')}</div><div><b>Tujuanmu, rencanamu.</b><span>Setiap orang punya titik mulai.</span></div></div><div class="floating hero-mini"><div class="mini-label">Roadmap Frontend <span class="tiny-pill">CONTOH</span></div><div class="mini-step"><span>✓</span> HTML & CSS</div><div class="mini-step"><span>2</span> JavaScript & interaksi</div><div class="mini-step"><span>3</span> Proyek pertamamu</div></div></div></div></section><section class="audience-strip"><div class="container audience-inner"><div class="audience-title">Ada tempat untuk setiap titik mulai.</div><div class="audience-item">${icon('grad')} Mahasiswa baru & akhir</div><div class="audience-item">${icon('code')} Pemula yang ingin belajar IT</div><div class="audience-item">${icon('briefcase')} Pekerja & career switcher</div></div></section><section class="section"><div class="container"><div class="section-heading"><div><div class="eyebrow">Temukan tujuan belajarmu</div><h2>Mau ke arah mana?</h2></div><a class="text-link" href="#/careers">Lihat semua jalur ${icon('arrow',true)}</a></div><div class="career-grid">${[careers[0],careers[1],careers[2]].map(careerCard).join('')}</div></div></section><section class="section how-section" id="how"><div class="container"><div class="section-heading"><div><div class="eyebrow">Cara kerja CareerPilot AI</div><h2>Dari profil, jadi rencana belajar.</h2></div><p>Kamu tentukan tujuannya. Kami bantu menyusun langkah yang bisa kamu ikuti.</p></div><div class="steps-grid"><div class="how-step"><div class="step-no">01</div><h3>Kenali titik mulamu</h3><p>Isi kemampuan dan pengalamanmu. Kamu juga bisa mencoba simulasi upload CV dengan profil contoh.</p></div><div class="how-step"><div class="step-no">02</div><h3>Pilih arah karier</h3><p>Jelajahi pilihan bidang IT, lalu pilih tujuan yang paling ingin kamu pelajari.</p></div><div class="how-step"><div class="step-no">03</div><h3>Ikuti roadmap-mu</h3><p>Lihat urutan materi, sumber belajar, dan latihan proyek untuk setiap tahap.</p></div></div></div></section><section class="section"><div class="container feature-section"><div class="feature-visual"><img src="assets/study.jpg" alt="Menulis rencana belajar di meja" loading="lazy" width="1100" height="733"><div class="feature-note"><div class="row"><div class="soft-icon green">${icon('check')}</div><div><b>Belajar dengan langkah yang jelas</b><p class="small">Materi, latihan, lalu proyek.</p></div></div></div></div><div class="feature-copy"><div class="eyebrow">Belajar sesuai keadaanmu</div><h2>Kamu tidak harus<br>mulai dari nol lagi.</h2><p>Gunakan kemampuan yang sudah kamu punya sebagai bekal. Atur waktu belajar dan pilih materi yang sesuai dengan anggaranmu.</p><div class="feature-point">${icon('check')}<div><b>Urutan materi yang bisa diikuti</b><p>Setiap tahap punya fokus dan latihan yang jelas.</p></div></div><div class="feature-point">${icon('check')}<div><b>Ada pilihan sumber belajar gratis</b><p>Mulai dari dokumentasi dan materi yang bisa diakses langsung.</p></div></div><div class="feature-point">${icon('check')}<div><b>Rencana bisa dievaluasi kembali</b><p>Paket Plus membantu menyesuaikan langkah setelah kamu berkembang.</p></div></div><button class="text-link" data-action="start">Coba susun rencana ${icon('arrow',true)}</button></div></div></section><section class="section pricing-wrap" id="plans"><div class="container"><div class="center-heading"><div class="eyebrow">Free & Plus</div><h2>Mulai gratis. Lanjut sesuai kebutuhan.</h2><p>Coba roadmap awal dengan Free, atau jelajahi fitur pemantauan dan evaluasi di simulasi Plus.</p></div><div class="pricing-grid">${pricingCard('free')}${pricingCard('plus')}</div><details class="pricing-details"><summary>Bandingkan semua fitur Free & Plus ${icon('chevron',true)}</summary>${comparison()}</details></div></section><section class="section"><div class="container faq-grid"><div class="faq-intro"><div class="eyebrow">Sebelum mulai</div><h2>Masih ada<br>yang ingin ditanyakan?</h2><p>Beberapa hal yang perlu kamu tahu saat mencoba CareerPilot AI.</p></div><div><details class="faq-item" open><summary>Apakah harus sudah punya pengalaman IT?</summary><p>Tidak harus. Kamu bisa mulai sebagai pemula, mahasiswa, atau orang yang ingin pindah bidang. Isi kemampuanmu sesuai keadaan sekarang.</p></details><details class="faq-item"><summary>Apa perbedaan Free dan Plus?</summary><p>Free menyediakan profil, roadmap awal, rekomendasi materi dan proyek, ringkasan skill, serta bookmark. Plus menambahkan evaluasi ulang, pembaruan roadmap, progres, target mingguan, riwayat evaluasi, dan laporan perkembangan.</p></details><details class="faq-item"><summary>Apakah saya perlu mengunggah CV asli?</summary><p>Untuk prototype ini, tombol upload memakai CV contoh. Tidak ada file yang dikirim dan tidak ada pembayaran. Semua hasil rekomendasi merupakan simulasi.</p></details><details class="faq-item"><summary>Apakah roadmap menjamin mendapat pekerjaan?</summary><p>Tidak. Roadmap membantu menyusun proses belajar. Kesiapan kerja tetap dipengaruhi latihan, pengalaman, portofolio, dan kebutuhan perusahaan.</p></details></div></div></section><div class="container"><section class="final-cta"><div><h2>Mulai dari kemampuan<br>yang kamu punya.</h2><p>Pilih tujuan dan lihat contoh langkah belajar pertamamu.</p></div><button class="btn white" data-action="start">Buat roadmap gratis ${icon('arrow',true)}</button></section></div></main>${footer()}`;}

const planFeatures = [
 ['Mengisi profil, kemampuan, dan tujuan belajar',1,1],
 ['Membuat roadmap belajar awal',1,1],
 ['Rekomendasi course, materi, dan proyek',1,1],
 ['Evaluasi ulang kemampuan setelah belajar',0,1],
 ['Memperbarui roadmap sesuai perkembangan',0,1],
 ['Memantau progres belajar secara berkala',0,1],
 ['Simulasi upload CV dan edit profil',1,1],
 ['Enam pilihan jalur karier',1,1],
 ['Ringkasan bekal dan skill yang perlu dipelajari',1,1],
 ['Bookmark sumber belajar',1,1],
 ['Unduh roadmap belajar',1,1],
 ['Checklist tugas di setiap tahap',0,1],
 ['Target belajar mingguan',0,1],
 ['Riwayat perubahan roadmap',0,1],
 ['Unduh laporan perkembangan belajar',0,1]
];


function pricingCard(plan){
 const plus=plan==='plus';
 const features=[['Profil manual & simulasi CV',true],['Roadmap awal & pilihan karier',true],['Ringkasan skill yang perlu dipelajari',true],['Materi, proyek, dan bookmark',true],['Unduh roadmap belajar',true],['Evaluasi ulang & pembaruan roadmap',plus],['Checklist, progres, dan target mingguan',plus],['Riwayat roadmap & laporan progres',plus]];
 return `<article class="pricing-card${plus?' plus':''}">${plus?'<span class="popular-tag">Untuk belajar berkelanjutan</span>':''}<div class="price-eyebrow">${plus?'PLUS':'FREE'}</div><h3>${plus?'Ikuti perkembanganmu':'Roadmap pertamamu'}</h3><p>${plus?'Rencana langganan bulanan · Simulasi tanpa biaya':'Gratis untuk mulai menyusun arah belajar'}</p><ul class="plan-features">${features.map(([t,a])=>`<li class="${a?'':'dim'}">${icon(a?'check':'lock',true)}${t}</li>`).join('')}</ul><button class="btn full ${plus?'':'outline'}" data-action="${plus?'try-plus':'start-free'}">${plus?'Coba simulasi Plus':'Mulai dengan Free'} ${icon('arrow',true)}</button><p class="plan-footer-note">${plus?'Tidak ada transaksi atau tagihan.':'Tanpa kartu pembayaran.'}</p></article>`;
}
function catalog(){return `${header()}<main id="main-content" class="fade-in"><section class="page-top"><div class="container"><div class="eyebrow">Pilih arah, mulai bertahap</div><h1>Temukan jalur kariermu.</h1><p>Jelajahi bidang yang ingin kamu pelajari. Roadmap akan mengikuti profil dan waktu belajar yang kamu masukkan.</p></div></section><section class="container catalog-layout"><div class="filter-row"><div class="filter-buttons" role="group" aria-label="Filter bidang">${[['all','Semua bidang'],['development','Development'],['data','Data'],['design','Desain'],['infrastructure','Infrastruktur']].map(([id,t])=>`<button class="filter-btn${ui.category===id?' active':''}" data-action="career-filter" data-filter="${id}" aria-pressed="${ui.category===id}">${t}</button>`).join('')}</div><div class="search-box">${icon('search')}<input id="career-search" aria-label="Cari jalur karier" placeholder="Cari jalur karier..." value="${esc(ui.careerSearch)}"></div></div><div class="career-grid">${careers.map(careerCard).join('')}</div><div class="empty-state hide" id="career-empty"><h2>Jalurnya belum ditemukan.</h2><p>Coba kata kunci lain atau pilih semua bidang.</p></div></section></main>${footer()}`;}
function onboardingHeader(){return `<header class="onboard-header"><nav class="container nav">${logo()}<div class="row"><span class="demo-label">SESI DEMO</span>${tag()}<a class="text-link" href="#/home" aria-label="Kembali ke beranda">${icon('close')}</a></div></nav></header>`;}
function steps(){return `<div class="onboard-steps" aria-label="Tahap pembuatan roadmap">${['Profil kamu','Pilih karier','Roadmap'].map((t,i)=>`<div class="onboard-step${state.step===i+1?' active':state.step>i+1?' done':''}"><i>${state.step>i+1?'✓':i+1}</i>${t}</div>`).join('')}</div>`;}
function onboard(){return `<div class="onboard-page">${onboardingHeader()}<main id="main-content" class="onboard-shell fade-in">${steps()}${state.step===2?careerChoice():profileForm()}</main></div>`;}
function profileForm(){const p=state.profile;return `<div class="form-layout"><section class="panel"><div class="form-title"><div class="eyebrow">Langkah 01</div><h1>Kenalan dengan kemampuanmu.</h1><p>Isi profil secara manual atau gunakan CV contoh untuk mencoba alurnya.</p></div><div class="upload-zone${state.cvLoaded?' success':''}"><div class="soft-icon">${icon(state.cvLoaded?'file':'upload')}</div><h3>${ui.uploading?'Membaca CV contoh...':state.cvLoaded?'CV_Raka_Pratama.pdf':'Mulai dari CV yang sudah ada'}</h3><p>${state.cvLoaded?'Profil contoh sudah terisi. Kamu tetap bisa mengubahnya.':'Tombol ini memakai CV dummy, tanpa mengirim file apa pun.'}</p><button class="btn outline small-btn" data-action="upload"${ui.uploading?' disabled':''}>${ui.uploading?'<span class="spinner" style="border-color:#7656d633;border-top-color:#7656d6"></span>':icon(state.cvLoaded?'refresh':'upload',true)} ${state.cvLoaded?'Gunakan ulang CV contoh':'Upload CV demo'}</button></div><form id="profile-form"><div class="form-grid"><label class="wide">Nama kamu<input name="name" required maxlength="60" autocomplete="name" placeholder="Masukkan nama" value="${esc(p.name)}"></label><label>Posisimu sekarang<select name="level">${['Mahasiswa baru','Mahasiswa','Mahasiswa tingkat akhir','Lulusan baru','Pemula non-IT','Pekerja / career switcher'].map(l=>`<option${p.level===l?' selected':''}>${l}</option>`).join('')}</select></label><label>Waktu belajar per minggu<select name="hours">${[4,8,12].map(h=>`<option value="${h}"${Number(p.hours)===h?' selected':''}>${h} jam / minggu</option>`).join('')}</select></label><div class="wide"><label>Kemampuan yang sudah kamu pelajari</label><div class="skill-options">${skillOptions(p.skills)}</div><p class="small" style="margin-top:7px">Boleh dikosongkan kalau kamu baru mulai.</p></div><label class="wide">Pengalaman singkat <span class="muted">(opsional)</span><textarea name="experience" maxlength="500" placeholder="Contoh: pernah membuat halaman profil sederhana">${esc(p.experience)}</textarea></label><label class="wide">Pilihan anggaran belajar<select name="budget">${['Gratis','Utamakan gratis, terbuka untuk berbayar'].map(b=>`<option${p.budget===b?' selected':''}>${b}</option>`).join('')}</select></label></div><label class="consent-label"><input name="consent" type="checkbox" required${state.consent?' checked':''}><span>Saya setuju data profil ini dipakai untuk menyusun roadmap di sesi demo. Data tersimpan di browser ini dan dapat saya hapus.</span></label><div class="form-actions"><a class="text-link" href="#/home">Kembali</a><button class="btn" type="submit">Lanjut pilih karier ${icon('arrow',true)}</button></div></form></section><aside class="form-aside"><div class="soft-icon" style="background:#fff">${icon('route')}</div><h3>Kemampuanmu jadi titik awal.</h3><p>Profil ini membantu menyusun contoh urutan belajar dan memperkirakan durasinya.</p><div class="aside-list"><div class="row">${icon('check')}<span>Kamu bisa mulai tanpa CV dan tanpa pengalaman IT.</span></div><div class="row">${icon('clock')}<span>Waktu belajar bisa kamu sesuaikan dengan kegiatan sehari-hari.</span></div><div class="row">${icon('book')}<span>Ada sumber belajar gratis dan proyek untuk latihan.</span></div><div class="row">${icon('shield')}<span>Kamu dapat mengoreksi profil dan menghapus data demo.</span></div></div><div class="aside-note">Prototype ini menggunakan rekomendasi contoh, belum melakukan analisis AI terhadap CV asli.</div></aside></div>`;}
function careerChoice(){const c=career();return `<div class="onboard-choice-title"><div class="eyebrow">Langkah 02</div><h1>Kamu ingin belajar ke arah mana?</h1><p>Pilih satu tujuan dulu. Kamu masih bisa mengganti arah belajar nanti.</p></div><div class="choice-grid" role="group" aria-label="Pilihan karier">${careers.map(c=>{const match=c.skills.filter(s=>state.profile.skills.includes(s)).length;return `<button class="choice-card${state.career===c.id?' selected':''}" data-action="select-career" data-career="${c.id}" aria-pressed="${state.career===c.id}"><span class="selection-dot">${state.career===c.id?icon('check',true):''}</span><div class="soft-icon" style="background:${c.color};color:${c.ink}">${icon(c.icon)}</div><h3>${c.name}</h3><p>${c.desc}</p><span class="tiny-pill">${match?'Punya bekal '+match+' dari '+c.skills.length+' skill dasar':'Bisa mulai dari dasar'}</span></button>`;}).join('')}</div><div class="choice-footer"><div><strong>${c.name}</strong><p>Estimasi ${weeks()} minggu dengan ${state.profile.hours} jam belajar per minggu. Durasi bisa berubah.</p></div><div class="row"><button class="text-link" data-action="profile-back">Kembali</button><button class="btn" data-action="generate"${ui.generating?' disabled':''}>${ui.generating?'<span class="spinner"></span> Menyusun roadmap...':'Buat roadmap saya '+icon('arrow',true)}</button></div></div>`;}
const sideItems=[['dashboard','grid','Ringkasan'],['roadmap','route','Roadmap saya'],['resources','book','Materi belajar'],['progress','chart','Progres'],['profile','user','Profil & paket']];
function appShell(content){const current=route();const label=sideItems.find(s=>s[0]===current)?.[2]||'Ringkasan';const initial=esc(state.profile.name.trim().charAt(0).toUpperCase()||'R');return `<div class="app-layout"><aside class="sidebar">${logo()}<div class="sidebar-caption">RUANG BELAJARMU</div><nav class="sidebar-nav" aria-label="Navigasi aplikasi">${sideItems.map(([r,i,t])=>`<a class="side-link${r===current?' active':''}" href="#/${r}"${r===current?' aria-current="page"':''}>${icon(i)}<span>${t}</span></a>`).join('')}</nav><div class="side-bottom">${state.plan==='free'?`<div class="side-plus">${icon('sparkle')}<h4>Rencanamu bisa berkembang.</h4><p>Coba evaluasi ulang dan pantau belajarmu dengan Plus.</p><button class="btn" data-action="upgrade">Jelajahi Plus ${icon('arrow',true)}</button></div>`:`<div class="side-plus"><span class="tag plus-tag">${icon('sparkle',true)} Plus aktif</span><h4>Selangkah demi selangkah.</h4><p>Catat progres dan perbarui roadmap saat kemampuanmu bertambah.</p></div>`}<a href="#/home" class="side-link">${icon('home')}<span>Kembali ke beranda</span></a></div></aside><div class="app-body"><header class="app-topbar">${logo(true)}<div class="breadcrumb">Ruang belajar <span style="margin:0 9px">/</span> <b>${label}</b></div><div class="user-tools"><span class="demo-label">SESI DEMO</span><label class="plan-switch"><span>Paket demo</span><select id="plan-switch" aria-label="Pilih paket demo"><option value="free"${state.plan==='free'?' selected':''}>Free</option><option value="plus"${state.plan==='plus'?' selected':''}>Plus</option></select></label><a href="#/profile" class="row" aria-label="Buka profil"><div class="avatar">${initial}</div><div class="account-name">${esc(state.profile.name.split(' ')[0])}<small>Profil contoh / demo</small></div></a></div></header><main id="main-content" class="app-main fade-in">${content}</main></div></div>`;}
function pageHeading(title,desc,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function statCards(){const p=progress();return `<div class="stats-grid"><div class="stat-card"><div class="soft-icon">${icon('clock')}</div><div><div class="stat-value">${weeks()} <span style="font-size:12px;font-weight:600">minggu</span></div><div class="stat-label">Perkiraan durasi belajar</div></div></div><div class="stat-card"><div class="soft-icon orange">${icon('route')}</div><div><div class="stat-value">6 <span style="font-size:12px;font-weight:600">tahap</span></div><div class="stat-label">Dari fondasi sampai proyek</div></div></div><div class="stat-card"><div class="soft-icon green">${icon('check')}</div><div><div class="stat-value">${state.plan==='plus'?p.percent+'<span style="font-size:13px">%</span>':'Plus'}</div><div class="stat-label">${state.plan==='plus'?'Progres dari checklist-mu':'Progres tersedia di Plus'}</div></div></div></div>`;}
function dashboard(){const c=career(),p=progress(),a=activeStage(),first=esc(state.profile.name.trim().split(' ')[0]);return appShell(`${pageHeading(`Halo, ${first}. Siap belajar?`,'Ada langkah kecil yang bisa kamu mulai hari ini.',tag())}<section class="goal-banner"><div><div class="eyebrow">TUJUAN BELAJARMU</div><h2>${c.name}</h2><p>${c.desc} Kamu punya ${state.profile.hours} jam per minggu untuk mengikuti rencana ini.</p><a class="text-link" href="#/roadmap" style="margin-top:17px">Buka roadmap saya ${icon('arrow',true)}</a></div><div class="goal-symbol" aria-hidden="true">${esc(c.symbol)}</div></section>${statCards()}${skillGapPanel()}<div class="dashboard-cols"><section class="panel"><div class="panel-heading"><h2>Langkah belajarmu</h2><a class="text-link" href="#/roadmap">Lihat lengkap ${icon('arrow',true)}</a></div>${c.stages.slice(0,4).map((s,i)=>`<a class="preview-stage" href="#/roadmap"><div class="stage-number${stageProgress(i)===100?' complete':''}">${stageProgress(i)===100?'✓':String(i+1).padStart(2,'0')}</div><div><h3>${s.title}</h3><p>${stageProgress(i)===100?'Selesai dipelajari':known(s)?'Sudah punya dasar · bisa kamu tinjau kembali':s.skills.length?s.skills.join(', '):'Latihan & pemahaman dasar'}</p></div>${icon('chevron',true)}</a>`).join('')}</section><section class="panel"><div class="panel-heading"><h2>Mulai dari sini</h2><span class="tag">Tahap ${a+1}</span></div><div class="next-task"><div class="career-category">Latihan proyek</div><h3>${c.stages[a].title}</h3><p>${c.stages[a].project}</p><a class="btn small-btn" href="#/roadmap">Lihat langkahnya ${icon('arrow',true)}</a></div><div class="row between" style="margin-bottom:12px"><b style="font-size:11px">Progres belajar</b><span class="small muted">${state.plan==='plus'?p.done+'/'+p.total+' tugas':'Fitur Plus'}</span></div><div class="progress-track"><span style="width:${state.plan==='plus'?p.percent:0}%"></span></div><div class="progress-caption"><span>${state.plan==='plus'?'Berdasarkan checklist yang kamu isi':'Aktifkan Plus untuk mencatat progres'}</span><b>${state.plan==='plus'?p.percent+'%':'Plus'}</b></div><button class="text-link" style="margin-top:20px;font-size:11px" data-action="evaluate">${icon(state.plan==='plus'?'refresh':'lock',true)} Evaluasi ulang kemampuan</button></section></div><div class="notice" style="margin-top:22px;margin-bottom:0">${icon('info')}<span>Ini roadmap contoh untuk demonstrasi. Estimasi durasi dan rekomendasi dapat berubah setelah validasi kebutuhan pengguna.</span></div>`);}
function roadmapView(){const c=career(),p=progress();return appShell(`${pageHeading('Roadmap belajar saya',c.name+' · '+state.profile.hours+' jam belajar per minggu',`<button class="btn outline small-btn" data-action="download">${icon('download',true)} Unduh roadmap</button>`)}<div class="notice">${icon('info')}<span>Roadmap simulasi dari profilmu. Bagian yang sudah kamu kenal tetap bisa ditinjau. ${state.plan==='free'?'Semua tahap dan materi bisa dibaca gratis. Checklist progres tersedia di Plus.':'Tandai tugas yang benar-benar sudah kamu selesaikan.'}</span></div><div class="roadmap-layout"><div>${c.stages.map((s,i)=>`<details class="roadmap-card${stageProgress(i)===100?' complete':''}"${i===activeStage()?' open':''}><summary class="roadmap-summary"><span class="stage-number${stageProgress(i)===100?' complete':''}">${stageProgress(i)===100?'✓':String(i+1).padStart(2,'0')}</span><div><h3>${s.title}</h3><p>Est. ${Math.round(c.hours/6)} jam ${known(s)?' · Sudah punya dasar':''}</p></div><span class="chevron">${icon('chevron',true)}</span></summary><div class="roadmap-detail"><p>${s.desc}</p>${s.skills.length?`<div class="mini-chips">${s.skills.map(k=>`<span class="mini-chip">${k}</span>`).join('')}</div>`:''}${s.res.map(r=>`<a class="text-link" style="font-size:10px;margin-right:13px" href="${resources[r].url}" target="_blank" rel="noopener noreferrer">${icon('book',true)} ${resources[r].provider} ${icon('out',true)}</a>`).join('')}<div class="project-box"><b>LATIHAN PROYEK</b><p>${s.project}</p></div>${s.tasks.map((t,j)=>`<label class="task-row${state.tasks[taskKey(i,j)]?' done':''}"><input type="checkbox" data-action="toggle-task" data-stage="${i}" data-task="${j}"${state.tasks[taskKey(i,j)]?' checked':''}${state.plan==='free'?' aria-describedby="free-task-note"':''}><span>${t}</span></label>`).join('')}${state.plan==='free'?`<button class="locked-task" data-action="upgrade" id="${i===0?'free-task-note':'free-task-note-'+i}">${icon('lock',true)} Coba Plus untuk menyimpan checklist.</button>`:''}</div></details>`).join('')}</div><aside class="roadmap-aside"><div class="panel"><h3>Rencana pribadimu</h3><div class="info-pair"><span>Tujuan</span><b>${c.name}</b></div><div class="info-pair"><span>Waktu belajar</span><b>${state.profile.hours} jam / minggu</b></div><div class="info-pair"><span>Perkiraan durasi</span><b>${weeks()} minggu</b></div><div class="info-pair"><span>Sumber belajar</span><b>Utamakan gratis</b></div><div class="form-divider" style="margin:18px 0"></div>${state.plan==='plus'?`<div class="progress-track"><span style="width:${p.percent}%"></span></div><div class="progress-caption"><span>${p.done} dari ${p.total} tugas</span><b>${p.percent}%</b></div>`:`<button class="text-link" data-action="upgrade" style="font-size:11px">${icon('lock',true)} Pantau progres dengan Plus</button>`}<button class="text-link" style="font-size:10px;margin-top:17px" data-action="change-career">Ganti tujuan belajar ${icon('arrow',true)}</button></div><div class="upgrade-panel">${icon(state.plan==='plus'?'refresh':'sparkle')}<h3>${state.plan==='plus'?'Kemampuanmu sudah bertambah?':'Roadmap bisa ikut berkembang.'}</h3><p>${state.plan==='plus'?'Tambahkan kemampuan yang baru kamu pelajari. Tinjau kembali tahap yang masih perlu kamu latih.':'Coba Plus untuk evaluasi ulang kemampuan dan pemantauan belajar secara berkala.'}</p><button class="btn full small-btn" data-action="evaluate">${state.plan==='plus'?'Evaluasi ulang':'Jelajahi Plus'} ${icon('arrow',true)}</button>${state.lastEvaluation?`<p style="font-size:9px;margin:12px 0 0">Evaluasi terakhir: ${dateLabel(state.lastEvaluation.date)}</p>`:''}</div></aside></div>`);}
function resourcesView(){const ids=career().resources;const shown=ui.resourceFilter==='saved'?ids.filter(x=>state.saved.includes(x)):ids;return appShell(`${pageHeading('Materi untuk langkah berikutnya','Pilihan sumber belajar untuk jalur '+career().name+'.')}<div class="filter-buttons" style="margin-bottom:22px"><button class="filter-btn${ui.resourceFilter==='all'?' active':''}" data-action="resource-filter" data-filter="all">Semua materi</button><button class="filter-btn${ui.resourceFilter==='saved'?' active':''}" data-action="resource-filter" data-filter="saved">Disimpan (${ids.filter(x=>state.saved.includes(x)).length})</button></div><div class="resource-grid">${shown.length?shown.map(id=>{const r=resources[id],saved=state.saved.includes(id);return `<article class="resource-card"><div class="row between"><div class="soft-icon">${icon(r.icon)}</div><span class="tag green-tag">Gratis diakses</span></div><h3>${r.title}</h3><div class="resource-provider" style="margin-bottom:12px">${r.provider} · ${r.type}</div><p>${r.desc}</p><div class="resource-actions"><a class="text-link" href="${r.url}" target="_blank" rel="noopener noreferrer">Buka materi ${icon('out',true)}</a><button class="bookmark-btn${saved?' saved':''}" data-action="bookmark" data-resource="${id}" aria-label="${saved?'Hapus simpanan':'Simpan'} ${r.title}" aria-pressed="${saved}">${icon('bookmark')}</button></div></article>`;}).join(''):`<div class="empty-state"><div class="soft-icon">${icon('bookmark')}</div><h2>Belum ada materi disimpan.</h2><p>Tekan ikon bookmark pada materi yang ingin kamu pelajari nanti.</p><button class="text-link" data-action="resource-filter" data-filter="all" style="margin-top:20px">Lihat semua materi ${icon('arrow',true)}</button></div>`}</div><div class="notice" style="margin-top:23px">${icon('info')}<span>Materi membuka situs penyedia. Beberapa latihan dapat memerlukan akun. CareerPilot AI belum memiliki kerja sama dengan penyedia yang tercantum.</span></div>`);}

function skillGapPanel(){
 const c=career(),have=c.skills.filter(s=>state.profile.skills.includes(s)),missing=c.skills.filter(s=>!state.profile.skills.includes(s));
 return `<section class="panel skill-gap-panel"><div class="panel-heading"><h2>Bekalmu & langkah yang masih perlu dipelajari</h2><span class="tag">${have.length}/${c.skills.length} skill dasar</span></div><div class="skill-gap-grid"><div><div class="skill-gap-label">${icon('check',true)} Sudah kamu pelajari</div><div class="mini-chips">${have.length?have.map(s=>`<span class="mini-chip have-skill">${s}</span>`).join(''):'<p class="small">Belum ada yang dicatat. Kamu bisa mulai dari dasar.</p>'}</div></div><div><div class="skill-gap-label">${icon('target',true)} Perlu dikembangkan</div><div class="mini-chips">${missing.length?missing.map(s=>`<span class="mini-chip">${s}</span>`).join(''):'<p class="small">Dasar sudah tercatat. Lanjutkan latihan dan proyek di roadmap.</p>'}</div></div></div><p class="skill-gap-note">Ringkasan mengikuti kemampuan yang kamu isi. Ini bukan hasil tes atau penilaian kesiapan kerja.</p></section>`;
}
function weeklyStats(){
 const now=new Date(),start=new Date(now);start.setHours(0,0,0,0);start.setDate(start.getDate()-((start.getDay()+6)%7));
 const currentTasks=new Map();career().stages.forEach((s,i)=>s.tasks.forEach((t,j)=>currentTasks.set(t,taskKey(i,j))));
 const keys=new Set(state.activity.filter(a=>a.type==='task'&&new Date(a.date)>=start&&new Date(a.date)<=now&&(!a.career||a.career===state.career)).map(a=>a.key||currentTasks.get(a.text)).filter(k=>k&&state.tasks[k]));
 return {count:keys.size,goal:state.weeklyGoal,percent:Math.min(100,Math.round(keys.size/state.weeklyGoal*100)),start};
}
function weeklyPanel(){
 const w=weeklyStats();
 return `<section class="panel weekly-panel"><div class="panel-heading"><h2>Target minggu ini</h2><button class="text-link" data-action="weekly-goal">Atur target ${icon('pen',true)}</button></div><div class="weekly-target-number">${w.count}<span> / ${w.goal} tugas</span></div><p class="small" style="margin:5px 0 17px">${w.count>=w.goal?'Targetmu tercapai. Kamu bisa lanjut sesuai waktumu.':'Selesaikan satu tugas, lalu tandai di roadmap.'}</p><div class="progress-track"><span style="width:${w.percent}%"></span></div><div class="progress-caption"><span>Minggu dimulai ${new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short'}).format(w.start)}</span><b>${w.percent}%</b></div></section>`;
}
function currentHistory(){return state.evaluations.filter(x=>x.career===state.career);}
function historyItems(items){return items.map(e=>`<div class="history-item"><span class="history-version">v${e.version}</span><div><b>Roadmap dievaluasi kembali</b><p>${e.added?.length?'Ditambahkan: '+e.added.map(esc).join(', '):'Kemampuan ditinjau kembali.'}${e.removed?.length?' · Dikoreksi: '+e.removed.map(esc).join(', '):''}</p>${e.nextFocus?`<p>Fokus berikutnya: ${esc(e.nextFocus)}</p>`:''}<time>${dateLabel(e.date)}</time></div></div>`).join('');}
function historyPanel(){
 const history=currentHistory();
 return `<section class="panel history-panel"><div class="panel-heading"><h2>Riwayat roadmap</h2><button class="text-link" data-action="roadmap-history">Lihat riwayat ${icon('arrow',true)}</button></div>${history.length?historyItems(history.slice(0,2)):`<div class="history-empty">${icon('route')}<div><b>Belum ada evaluasi yang tercatat di riwayat.</b><p>Setelah evaluasi ulang, perubahan kemampuan dan fokus belajar akan tercatat di sini.</p></div><button class="text-link" data-action="evaluate">Mulai evaluasi</button></div>`}</section>`;
}
function weeklyGoalModal(){
 if(state.plan!=='plus'){upgrade();return;}
 modal(`<div class="soft-icon">${icon('target')}</div><h2 id="modal-title">Atur target minggu ini.</h2><p>Pilih jumlah tugas yang ingin kamu selesaikan. Sesuaikan dengan waktu belajarmu, ${state.profile.hours} jam per minggu.</p><form id="weekly-goal-form"><label style="margin-top:19px">Target tugas<select name="weeklyGoal">${[1,3,6,9,12,18].map(n=>`<option value="${n}"${state.weeklyGoal===n?' selected':''}>${n} tugas / minggu</option>`).join('')}</select></label><button class="btn full" type="submit" style="margin-top:23px">Simpan target ${icon('check',true)}</button></form>`);
}
function historyModal(){
 if(state.plan!=='plus'){upgrade();return;}
 const items=currentHistory();
 modal(`<div class="soft-icon">${icon('route')}</div><h2 id="modal-title">Riwayat roadmap kamu.</h2><p>${career().name} · Perubahan dari evaluasi yang kamu lakukan.</p><div style="margin-top:18px">${items.length?historyItems(items.slice(0,8)):'<div class="eval-summary"><b>Versi 1 · Roadmap awal</b><p style="margin-top:7px">Belum ada evaluasi ulang. Coba tambahkan kemampuan baru agar perubahan roadmap tercatat.</p></div>'}</div><button class="btn outline full" data-action="close-modal">Tutup riwayat</button>`);
}
function recordEvaluation(before){
 const skills=[...state.profile.skills],added=skills.filter(s=>!before.includes(s)),removed=before.filter(s=>!skills.includes(s));
 const version=Math.max(1,...currentHistory().map(x=>Number(x.version)||1))+1;
 const entry={career:state.career,version,date:new Date().toISOString(),before:[...before],skills,added,removed,nextFocus:career().stages[activeStage()].title};
 state.evaluations.unshift(entry);state.evaluations=state.evaluations.slice(0,50);state.lastEvaluation=entry;
 state.activity.unshift({type:'evaluation',career:state.career,text:'Evaluasi kemampuan diperbarui',detail:added.length?'Tambahan: '+added.join(', '):'Profil kemampuan ditinjau kembali',date:entry.date});state.activity=state.activity.slice(0,40);
}
function downloadReport(){
 if(state.plan!=='plus'){upgrade();return;}
 const p=progress(),w=weeklyStats(),history=currentHistory();
 const lines=['LAPORAN PERKEMBANGAN — CAREERPILOT AI','Profil: '+state.profile.name,'Jalur: '+career().name,'Dibuat: '+dateLabel(new Date().toISOString()),'Paket: Plus (simulasi)','',`PROGRES: ${p.done}/${p.total} tugas (${p.percent}%)`,`TARGET MINGGU INI: ${w.count}/${w.goal} tugas`,'Kemampuan tercatat: '+(state.profile.skills.join(', ')||'Mulai dari dasar'),'','PROGRES PER TAHAP',...career().stages.map((s,i)=>`${i+1}. ${s.title}: ${stageProgress(i)}%`),'','RIWAYAT EVALUASI',...(history.length?history.map(e=>`Versi ${e.version} — ${dateLabel(e.date)}\nTambahan kemampuan: ${e.added.join(', ')||'Tidak ada'}\nFokus berikutnya: ${e.nextFocus}`):['Belum ada evaluasi ulang.']),'','Data ini berasal dari input dan checklist sesi demo, bukan hasil tes kompetensi.'];
 const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}));a.download=`Laporan_Progres_${state.career}_CareerPilot_AI.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);showToast('Laporan perkembangan siap diunduh.');
}


function progressView(){
 if(state.plan==='free')return appShell(`${pageHeading('Progres belajar','Lihat perkembanganmu dari tugas yang kamu selesaikan.')}<section class="gate-panel"><div class="soft-icon">${icon('chart')}</div><span class="tag plus-tag" style="margin-bottom:15px">Fitur Plus</span><h2>Catat langkah yang sudah kamu lalui.</h2><p>Aktifkan simulasi Plus untuk memantau progres, mengatur target mingguan, dan mengevaluasi ulang kemampuan.</p><div class="gate-features"><span>${icon('check',true)} Checklist & target</span><span>${icon('check',true)} Riwayat roadmap</span><span>${icon('check',true)} Laporan progres</span></div><button class="btn" data-action="upgrade">Coba Plus tanpa pembayaran ${icon('arrow',true)}</button><p class="small" style="margin-bottom:0">Roadmap, ringkasan skill, dan sumber belajar tetap tersedia di paket Free.</p></section>`);
 const p=progress(),activity=state.activity.filter(a=>!a.career||a.career===state.career);
 return appShell(`${pageHeading('Sedikit demi sedikit, ada progres.','Perkembangan ini mengikuti checklist yang kamu isi.',`<div class="row wrap progress-actions"><button class="btn outline small-btn" data-action="download-report">${icon('download',true)} Unduh laporan</button><button class="btn small-btn" data-action="evaluate">${icon('refresh',true)} Evaluasi ulang</button></div>`)}${statCards()}<div class="dashboard-cols"><div class="stack"><section class="panel"><div class="panel-heading"><h2>Progres setiap tahap</h2><span class="tag">${p.percent}% total</span></div>${career().stages.map((s,i)=>`<div class="stage-bar-row"><span>${s.title}</span><div class="progress-track"><span style="width:${stageProgress(i)}%"></span></div><b>${stageProgress(i)}%</b></div>`).join('')}</section>${historyPanel()}</div><div class="stack">${weeklyPanel()}<section class="panel"><div class="panel-heading"><h2>Aktivitas terbaru</h2><span class="small muted">Sesi demo</span></div>${activity.length?`<div class="activity-list">${activity.slice(0,5).map(a=>`<div class="activity-row"><div class="soft-icon green" style="width:28px;height:28px;border-radius:8px">${icon(a.type==='evaluation'?'refresh':'check',true)}</div><div><h3>${esc(a.text)}</h3><p>${esc(a.detail||'Perkembangan belajar')}</p></div><time>${dateLabel(a.date)}</time></div>`).join('')}</div>`:`<div class="empty-state" style="padding:22px 0;border:0"><div class="soft-icon">${icon('book')}</div><h2 style="font-size:17px">Belum ada aktivitas.</h2><p>Mulai dari satu tugas di roadmap. Progresmu akan muncul di sini.</p><a class="text-link" href="#/roadmap" style="margin-top:18px">Buka roadmap ${icon('arrow',true)}</a></div>`}</section></div></div>`);
}

function comparison(){return `<div class="plan-comparison"><h2>Fitur paket Free dan Plus</h2><p class="small" style="margin-bottom:16px">Free membantu kamu memulai. Plus melanjutkan evaluasi dan pemantauan belajar.</p><table><thead><tr><th scope="col">Fitur aplikasi</th><th scope="col">Free</th><th scope="col">Plus</th></tr></thead><tbody>${planFeatures.map(([t,a,b],i)=>`<tr${i===6?' class="additional-features"':''}><td>${t}</td><td class="${a?'table-yes':'table-no'}" aria-label="${a?'Tersedia':'Tidak tersedia'}">${a?'✓':'—'}</td><td class="${b?'table-yes':'table-no'}" aria-label="${b?'Tersedia':'Tidak tersedia'}">${b?'✓':'—'}</td></tr>`).join('')}</tbody></table></div>`;}
function profileView(){const p=state.profile;return appShell(`${pageHeading('Profil & paket belajar','Koreksi profil dan pilih cara belajar yang kamu perlukan.')}<div class="profile-grid"><section class="panel"><div class="profile-card-header"><div class="avatar">${esc(p.name.charAt(0).toUpperCase())}</div><div><h2>${esc(p.name)}</h2><p>${esc(p.level)}</p></div></div><div class="info-pair"><span>Tujuan belajar</span><b>${career().name}</b></div><div class="info-pair"><span>Waktu belajar</span><b>${p.hours} jam / minggu</b></div><div class="info-pair"><span>Anggaran</span><b>${esc(p.budget)}</b></div><div class="mini-chips">${p.skills.length?p.skills.map(s=>`<span class="mini-chip">${s}</span>`).join(''):'<span class="small muted">Mulai dari dasar</span>'}</div>${p.experience?`<p class="small" style="margin-bottom:18px">${esc(p.experience)}</p>`:''}<button class="btn outline small-btn" data-action="edit-profile">${icon('pen',true)} Edit profil</button></section><section class="panel"><div class="row between" style="margin-bottom:20px"><h2 style="font-size:18px">Paket belajarmu</h2>${tag()}</div><h3 style="font-size:24px;margin:10px 0">${state.plan==='plus'?'Belajar berkelanjutan.':'Roadmap awal gratis.'}</h3><p style="font-size:12px;line-height:1.9">${state.plan==='plus'?'Checklist, progres, dan evaluasi ulang sudah aktif untuk sesi demo ini. Tidak ada transaksi atau tagihan.':'Roadmap, sumber belajar, dan proyek bisa kamu akses. Coba Plus untuk mencatat perkembangan dan mengevaluasi ulang kemampuan.'}</p><div class="form-divider"></div>${state.plan==='plus'?`<button class="btn outline small-btn" data-action="use-free">Kembali ke paket Free</button>`:`<button class="btn small-btn" data-action="upgrade">${icon('sparkle',true)} Coba simulasi Plus</button>`}<p class="small" style="margin-top:15px">Pilihan paket hanya berlaku pada prototype ini.</p></section></div>${comparison()}<div class="reset-note"><p>Data demo tersimpan di browser ini. Kamu dapat menghapus profil, roadmap, dan riwayatnya kapan saja.</p><button class="danger-link" data-action="reset">Hapus semua data demo</button></div>`);}
function filterCareers(){let count=0;$$('[data-career-card]').forEach(el=>{const c=careers.find(c=>c.id===el.dataset.careerCard);const visible=(ui.category==='all'||c.category===ui.category)&&`${c.name} ${c.label} ${c.desc}`.toLowerCase().includes(ui.careerSearch.toLowerCase());el.hidden=!visible;el.style.display=visible?'':'none';if(visible)count++;});$('#career-empty')?.classList.toggle('hide',count>0);}
function $$(s,root=document){return Array.from(root.querySelectorAll(s));}
function render(){let r=route();if(!['home','careers','onboarding',...sideItems.map(x=>x[0])].includes(r)){go('home');return;}if(['dashboard','roadmap','resources','progress','profile'].includes(r)&&!state.ready){state.step=1;go('onboarding');return;}const views={home,catalog,careers:catalog,onboarding:onboard,dashboard,roadmap:roadmapView,resources:resourcesView,progress:progressView,profile:profileView};$('#app').innerHTML=views[r]();document.title=(r==='home'?'Tentukan arah belajarmu':r==='careers'?'Pilihan jalur karier':r==='onboarding'?'Susun roadmap':sideItems.find(x=>x[0]===r)?.[2]||'CareerPilot')+' · CareerPilot AI';if(r==='careers')filterCareers();}
let lastFocus=null;
function closeModal(){const d=$('#demo-modal');if(d){d.close();$('#modal-root').innerHTML='';lastFocus?.focus?.();}}
function modal(content){closeModal();lastFocus=document.activeElement;$('#modal-root').innerHTML=`<dialog id="demo-modal" class="modal" aria-labelledby="modal-title"><button class="modal-x" data-action="close-modal" aria-label="Tutup dialog">${icon('close',true)}</button><div class="modal-inner">${content}</div></dialog>`;const d=$('#demo-modal');d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeModal();}});d.addEventListener('cancel',()=>{$('#modal-root').innerHTML='';lastFocus?.focus?.();});d.showModal();}

function upgrade(){modal(`<div class="soft-icon orange">${icon('sparkle')}</div><span class="tag plus-tag" style="margin-bottom:13px">CareerPilot Plus</span><h2 id="modal-title">Rencanamu ikut berkembang.</h2><p>Semua fitur Free tetap tersedia. Plus membantu kamu melanjutkan proses belajar secara berkala.</p><ul class="plan-features"><li>${icon('check',true)} Evaluasi ulang kemampuan setelah belajar.</li><li>${icon('check',true)} Perbarui fokus dan rekomendasi roadmap.</li><li>${icon('check',true)} Simpan checklist, progres, dan target mingguan.</li><li>${icon('check',true)} Tinjau riwayat perubahan roadmap.</li><li>${icon('check',true)} Unduh laporan perkembangan belajar.</li></ul><button class="btn full" data-action="activate-plus">Aktifkan simulasi Plus ${icon('arrow',true)}</button><p class="modal-note">Hanya perubahan paket demo. Tidak ada pembayaran.</p>`);}
function evaluate(){if(state.plan!=='plus'){upgrade();return;}modal(`<div class="soft-icon">${icon('refresh')}</div><h2 id="modal-title">Apa yang sudah kamu pelajari?</h2><p>Perbarui kemampuanmu. Roadmap contoh akan menandai fondasi yang sudah kamu miliki.</p><form id="evaluation-form"><div class="skill-options">${skillOptions(state.profile.skills)}</div><div class="eval-summary"><strong>${career().name}</strong><p style="font-size:11px;margin-top:6px">Checklist tugas tetap mengikuti hal yang kamu tandai sendiri. Evaluasi ini tidak otomatis menyelesaikan tugas.</p></div><button class="btn full" type="submit">Perbarui roadmap ${icon('refresh',true)}</button><p class="modal-note">Simulasi evaluasi, tanpa pemanggilan model AI.</p></form>`);}
function privacy(){modal(`<div class="soft-icon">${icon('shield')}</div><h2 id="modal-title">Kamu pegang kendali datamu.</h2><p>Tombol upload hanya mengisi CV contoh. Prototype ini tidak membaca CV asli, tidak mengirim data profil ke server, dan tidak memproses pembayaran.</p><p style="margin-top:13px">Profil, pilihan paket, serta progres demo disimpan di browser ini. Kamu bisa menghapus semuanya melalui halaman Profil & paket.</p><button class="btn full" data-action="close-modal" style="margin-top:22px">Mengerti</button>`);}
function readProfile(form){const f=new FormData(form);state.profile={name:String(f.get('name')||'').trim().slice(0,60),level:String(f.get('level')||'Mahasiswa'),hours:Number(f.get('hours'))||8,skills:f.getAll('skills').filter(s=>skillList.includes(s)),experience:String(f.get('experience')||'').slice(0,500),budget:String(f.get('budget')||'Gratis')};state.consent=f.get('consent')==='on';}
function uploadDemo(){if(ui.uploading)return;const form=$('#profile-form');if(form)readProfile(form);ui.uploading=true;render();setTimeout(()=>{state.profile={name:'Raka Pratama',level:'Mahasiswa',hours:8,skills:['HTML','CSS','Git'],experience:'Pernah membuat halaman profil sederhana dengan HTML dan CSS. Ingin belajar membangun website yang interaktif.',budget:'Gratis'};state.cvLoaded=true;ui.uploading=false;save();render();showToast('CV contoh digunakan. Profilnya bisa kamu koreksi.');},650);}
function generate(){if(ui.generating)return;ui.generating=true;render();setTimeout(()=>{ui.generating=false;state.ready=true;save();go('dashboard');showToast('Roadmap contoh siap. Selamat mulai belajar!');},650);}
function toggleTask(i,j){if(state.plan!=='plus'){upgrade();return;}const key=taskKey(i,j);state.tasks[key]=!state.tasks[key];if(state.tasks[key])state.activity.unshift({type:'task',career:state.career,key,text:career().stages[i].tasks[j],detail:career().stages[i].title,date:new Date().toISOString()});else state.activity=state.activity.filter(a=>a.type!=='task'||a.text!==career().stages[i].tasks[j]);state.activity=state.activity.slice(0,40);const open=$$('details.roadmap-card').map(x=>x.open);save();render();$$('details.roadmap-card').forEach((x,i)=>{x.open=!!open[i];});showToast(state.tasks[key]?'Satu langkah selesai. Progresmu tersimpan.':'Checklist diperbarui.');}
function download(){const c=career();const text=`ROADMAP BELAJAR — CAREERPILOT AI\nProfil: ${state.profile.name}\nTujuan: ${c.name}\nWaktu: ${state.profile.hours} jam per minggu\nEstimasi: ${weeks()} minggu\n\nRoadmap contoh untuk demonstrasi, bukan hasil analisis AI.\n\n`+c.stages.map((s,i)=>`${i+1}. ${s.title}\n${s.desc}\nLatihan proyek: ${s.project}\n${s.tasks.map((t,j)=>`[${state.tasks[taskKey(i,j)]?'x':' '}] ${t}`).join('\n')}\nSumber: ${s.res.map(r=>resources[r].url).join(', ')}\n`).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download=`Roadmap_${c.id}_CareerPilot_AI.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);showToast('Roadmap disiapkan untuk diunduh.');}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='toggle-task')e.preventDefault();switch(action){
 case 'skip':{e.preventDefault();const main=$('#main-content');if(main){main.tabIndex=-1;main.focus();}break;}
 case 'start':start();break;
 case 'start-free':start('free');break;
 case 'choose-start':start(state.plan,el.dataset.career);break;
 case 'try-plus':case 'upgrade':upgrade();break;
 case 'activate-plus':state.plan='plus';save();closeModal();if(state.ready)render();else start('plus');showToast('Simulasi Plus aktif. Tidak ada pembayaran.');break;
 case 'use-free':state.plan='free';save();render();showToast('Paket demo kembali ke Free.');break;
 case 'dashboard':if(state.ready)go('dashboard');else start();break;
 case 'menu':ui.menu=!ui.menu;render();break;
 case 'scroll':{const id=el.dataset.id;closeMobileMenu();if(route()!=='home'){go('home');setTimeout(()=>document.getElementById(id)?.scrollIntoView({behavior:'smooth'}),80);}else{if($('.nav-links'))$('.nav-links').classList.remove('open');document.getElementById(id)?.scrollIntoView({behavior:'smooth'});}break;}
 case 'career-filter':ui.category=el.dataset.filter;render();break;
 case 'upload':uploadDemo();break;
 case 'select-career':state.career=el.dataset.career;save();render();break;
 case 'profile-back':state.step=1;save();render();window.scrollTo(0,0);break;
 case 'generate':generate();break;
 case 'toggle-task':toggleTask(Number(el.dataset.stage),Number(el.dataset.task));break;
 case 'evaluate':evaluate();break;
 case 'weekly-goal':weeklyGoalModal();break;
 case 'roadmap-history':historyModal();break;
 case 'download-report':downloadReport();break;
 case 'download':download();break;
 case 'change-career':state.step=2;save();go('onboarding');break;
 case 'edit-profile':state.step=1;save();go('onboarding');break;
 case 'resource-filter':ui.resourceFilter=el.dataset.filter;render();break;
 case 'bookmark':{const id=el.dataset.resource;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();render();showToast(state.saved.includes(id)?'Materi disimpan untuk nanti.':'Materi dihapus dari simpanan.');break;}
 case 'privacy':privacy();break;
 case 'close-modal':closeModal();break;
 case 'reset':modal(`<div class="soft-icon orange">${icon('refresh')}</div><h2 id="modal-title">Mulai ulang sesi demo?</h2><p>Profil, pilihan paket, checklist, dan riwayat belajar akan dihapus dari browser ini.</p><div class="form-actions" style="margin-top:25px"><button class="btn outline" data-action="close-modal">Batal</button><button class="btn" data-action="confirm-reset">Hapus data demo</button></div>`);break;
 case 'confirm-reset':state=baseState();save();closeModal();ui.category='all';ui.careerSearch='';ui.resourceFilter='all';go('home');showToast('Data demo dihapus. Kamu bisa mulai lagi.');break;
 }});
document.addEventListener('input',e=>{if(e.target.id==='career-search'){ui.careerSearch=e.target.value;filterCareers();}});
document.addEventListener('change',e=>{if(e.target.id==='plan-switch'){if(e.target.value==='plus'&&state.plan!=='plus'){e.target.value=state.plan;upgrade();}else if(e.target.value==='free'){state.plan='free';save();render();showToast('Mode Free aktif.');}}});
document.addEventListener('submit',e=>{
 if(e.target.id==='profile-form'){
  e.preventDefault();readProfile(e.target);if(!state.profile.name||!state.consent)return;
  state.step=2;save();render();window.scrollTo(0,0);
 }
 if(e.target.id==='evaluation-form'){
  e.preventDefault();if(state.plan!=='plus'){upgrade();return;}
  const before=[...state.profile.skills];state.profile.skills=new FormData(e.target).getAll('skills').filter(x=>skillList.includes(x));
  recordEvaluation(before);save();closeModal();go('roadmap');showToast('Roadmap diperbarui. Perubahannya tercatat di riwayat.');
 }
 if(e.target.id==='weekly-goal-form'){
  e.preventDefault();if(state.plan!=='plus'){upgrade();return;}
  const goal=Number(new FormData(e.target).get('weeklyGoal'));if(![1,3,6,9,12,18].includes(goal))return;
  state.weeklyGoal=goal;save();closeModal();render();showToast('Target mingguan diperbarui.');
 }
});
document.addEventListener('click',e=>{
 if(ui.menu&&(e.target.closest('.nav-links a')||(!e.target.closest('.nav-links')&&!e.target.closest('.mobile-menu'))))closeMobileMenu();
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.menu){closeMobileMenu();$('.mobile-menu')?.focus();}});
window.addEventListener('hashchange',()=>{closeMobileMenu();closeModal();render();window.scrollTo(0,0);});
render();
